# Generated by build.py from recipe.yml for recipe amqp-send-and-receive. Do not edit.
Set-Location $PSScriptRoot
cmd /c 'openssl req -x509 -newkey rsa:2048 -nodes -keyout server.key -out server.pem -days 30 -subj "/CN=127.0.0.1" -addext "subjectAltName=IP:127.0.0.1"'
$server0 = Start-Process surl -ArgumentList '--user', 'alice:s3cret', '--cert', 'server.pem', '--key', 'server.key', 'amqps://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe --cacert server.pem -u alice:s3cret -d hello amqps://127.0.0.1:8080/%2F/orders --next --cacert server.pem -u alice:s3cret amqps://127.0.0.1:8080/%2F/orders } finally { Stop-Process $server0 }
